class Solution:
    def compareVersions(self, v1: str, v2: str) -> int:
        a = [int(p) for p in v1.split(".")]
        b = [int(p) for p in v2.split(".")]
        for i in range(max(len(a), len(b))):
            x = a[i] if i < len(a) else 0
            y = b[i] if i < len(b) else 0
            if x != y:
                return -1 if x < y else 1
        return 0

